import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:hive/hive.dart';
import 'package:nothingness/models/audio_track.dart';
import 'package:nothingness/services/playback_controller.dart';
import 'package:nothingness/services/playlist_store.dart';

import '../support/pump_until.dart';
import 'mock_audio_transport.dart';

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  late Directory tempDir;
  late MockAudioTransport transport;
  late PlaylistStore playlist;
  late PlaybackController controller;
  var testNumber = 0;

  List<AudioTrack> tracksFromFixture = [];

  // Smoke test: load 10 fixture media from /opt/nothingness/media and drive
  // play/pause, next and seek (fast-forward).

  List<AudioTrack> loadFixtureTracks() {
    // The code uses a real filesystem path; call scanFolder to read metadata
    // and create AudioTrack items for all media files in the folder.
    // This helper is synchronous here; actual loading happens via controller.scanFolder
    // which is async. We just provide the path for later use.
    return [];
  }

  setUp(() async {
    testNumber++;
    tempDir = await Directory.systemTemp.createTemp('fixture_media_smoke_$testNumber');
    Hive.init(tempDir.path);

    transport = MockAudioTransport();
    playlist = PlaylistStore(
      hive: Hive,
      hiveInitializer: () async {},
      boxOpener: (hive) => hive.openBox<dynamic>('playlistBox_$testNumber'),
    );

    controller = PlaybackController(
      transport: transport,
      playlist: playlist,
    );
    await controller.init();
  });

  tearDown(() async {
    await controller.shutdown();
    // Close only the box we opened, not all boxes
    try {
      if (Hive.isBoxOpen('playlistBox_$testNumber')) {
        await Hive.box('playlistBox_$testNumber').close();
      }
    } catch (_) {}
    if (tempDir.existsSync()) {
      await tempDir.delete(recursive: true);
    }
  });

  // =========================================================================
  // Smoke test using real fixture media
  // =========================================================================
  group('Fixture media smoke test (play/pause, next, seek)', () {
    test('loads fixture 10 tracks and plays first track', () async {
      // Load tracks from fixture folder
      final loaded = await controller.scanFolder('/opt/nothingness/media');
      tracksFromFixture = loaded;
      expect(tracksFromFixture.length, greaterThan(0), reason: 'Fixture folder should contain media files');

      await controller.setQueue(tracksFromFixture);
      // Wait for playback to start
      await pumpUntil(() => controller.isPlayingNotifier.value);

      // Basic assertions
      expect(controller.queueNotifier.value.length, tracksFromFixture.length);
      expect(transport.loadCalls.length, greaterThanOrEqualTo(1));
      expect(transport.playCalls.length, greaterThanOrEqualTo(1));
    });

    test('play/pause toggles', () async {
      // Ensure we have queued tracks
      if (tracksFromFixture.isEmpty) {
        final loaded = await controller.scanFolder('/opt/nothingness/media');
        tracksFromFixture = loaded;
        await controller.setQueue(tracksFromFixture);
        await pumpUntil(() => controller.isPlayingNotifier.value);
      }

      // Pause
      await controller.playPause();
      await pumpUntil(() => controller.isPlayingNotifier.value == false);
      expect(controller.isPlayingNotifier.value, false);
      expect(transport.pauseCalls.isNotEmpty, true);

      // Play again
      await controller.playPause();
      await pumpUntil(() => controller.isPlayingNotifier.value == true);
      expect(controller.isPlayingNotifier.value, true);
      expect(transport.playCalls.isNotEmpty, true);
    });

    test('skip to next track', () async {
      // Ensure we have queued tracks and playing
      if (tracksFromFixture.isEmpty) {
        final loaded = await controller.scanFolder('/opt/nothingness/media');
        tracksFromFixture = loaded;
        await controller.setQueue(tracksFromFixture);
        await pumpUntil(() => controller.isPlayingNotifier.value);
      }

      final initialIndex = controller.currentIndexNotifier.value ?? 0;
      await controller.next();
      // Wait for index to advance
      await pumpUntil(() => controller.currentIndexNotifier.value == initialIndex + 1 || controller.currentIndexNotifier.value == (tracksFromFixture.length - 1));
      final idx = controller.currentIndexNotifier.value ?? 0;
      expect(idx, isNonNull);
      // Ensure a new track loaded
      final expectedPath = tracksFromFixture[idx].path;
      await pumpUntil(() => transport.loadCalls.isNotEmpty && transport.loadedPath == expectedPath);
      expect(transport.loadedPath, expectedPath);
    });

    test('fast forward (seek) within current track', () async {
      // Ensure we have tracks
      if (tracksFromFixture.isEmpty) {
        final loaded = await controller.scanFolder('/opt/nothingness/media');
        tracksFromFixture = loaded;
        await controller.setQueue(tracksFromFixture);
        await pumpUntil(() => controller.isPlayingNotifier.value);
      }
      // Seek forward by 60 seconds
      await controller.seek(const Duration(seconds: 60));
      await pumpUntil(() => transport.seekCalls.isNotEmpty);
      expect(transport.seekCalls.isNotEmpty, true);
      expect(transport.seekCalls.last, const Duration(seconds: 60));
    });
  });
}

